import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useQuery } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { api } from "@/lib/api";
import type { Inquiry, InquiryType, InquiryPriority, InquiryStatus } from "@/types/api";

const inquirySchema = z.object({
  inquiry_date: z.string().min(1, "Inquiry date is required"),
  inquiry_type: z.string().min(1, "Inquiry type is required"),
  inquiry_source: z.string().optional(),
  client_name: z.string().min(1, "Client name is required"),
  requirement_summary: z.string().optional(),
  estimated_value: z.coerce.number().nullable().optional(),
  priority: z.string().min(1, "Priority is required"),
  status: z.string().min(1, "Status is required"),
  notes: z.string().optional(),
});

type InquiryFormData = z.infer<typeof inquirySchema>;

interface InquiryFormProps {
  initialData?: Partial<InquiryFormData>;
  onSubmit: (data: InquiryFormData) => Promise<void>;
  onCancel?: () => void;
  isLoading?: boolean;
}

export function InquiryForm({ initialData, onSubmit, onCancel, isLoading }: InquiryFormProps) {
  const form = useForm<InquiryFormData>({
    resolver: zodResolver(inquirySchema),
    defaultValues: {
      inquiry_date: new Date().toISOString().split("T")[0],
      inquiry_type: "MEP",
      inquiry_source: "",
      client_name: "",
      requirement_summary: "",
      estimated_value: null,
      priority: "medium",
      status: "open",
      notes: "",
      ...initialData,
    },
  });

  const { data: clientsData } = useQuery({
    queryKey: ["clients-list"],
    queryFn: () => api.listClients({ page: 1, page_size: 1000 }),
  });

  const clientNames = clientsData?.items.map((c) => c.name) ?? [];

  const handleSubmit = async (data: InquiryFormData) => {
    await onSubmit(data);
  };

  return (
    <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Inquiry Details</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="inquiry_date">Inquiry Date *</Label>
              <Input id="inquiry_date" type="date" {...form.register("inquiry_date")} />
              {form.formState.errors.inquiry_date && (
                <p className="text-sm text-red-500">{form.formState.errors.inquiry_date.message}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="inquiry_type">Inquiry Type *</Label>
              <Select
                value={form.watch("inquiry_type")}
                onValueChange={(v) => form.setValue("inquiry_type", v)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select type" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="MEP">MEP</SelectItem>
                  <SelectItem value="Structural">Structural</SelectItem>
                  <SelectItem value="Green Building">Green Building</SelectItem>
                  <SelectItem value="Fire Safety">Fire Safety</SelectItem>
                  <SelectItem value="Other">Other</SelectItem>
                </SelectContent>
              </Select>
              {form.formState.errors.inquiry_type && (
                <p className="text-sm text-red-500">{form.formState.errors.inquiry_type.message}</p>
              )}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="client_name">Client Name *</Label>
              <Input
                id="client_name"
                list="client-names"
                placeholder="Select or type client name"
                {...form.register("client_name")}
              />
              <datalist id="client-names">
                {clientNames.map((name) => (
                  <option key={name} value={name} />
                ))}
              </datalist>
              {form.formState.errors.client_name && (
                <p className="text-sm text-red-500">{form.formState.errors.client_name.message}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="inquiry_source">Inquiry Source</Label>
              <Input id="inquiry_source" {...form.register("inquiry_source")} />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="requirement_summary">Requirement Summary</Label>
            <Textarea id="requirement_summary" {...form.register("requirement_summary")} />
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label htmlFor="estimated_value">Estimated Value (₹)</Label>
              <Input
                id="estimated_value"
                type="number"
                {...form.register("estimated_value")}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="priority">Priority *</Label>
              <Select
                value={form.watch("priority")}
                onValueChange={(v) => form.setValue("priority", v)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select priority" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="low">Low</SelectItem>
                  <SelectItem value="medium">Medium</SelectItem>
                  <SelectItem value="high">High</SelectItem>
                  <SelectItem value="critical">Critical</SelectItem>
                </SelectContent>
              </Select>
              {form.formState.errors.priority && (
                <p className="text-sm text-red-500">{form.formState.errors.priority.message}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="status">Status *</Label>
              <Select
                value={form.watch("status")}
                onValueChange={(v) => form.setValue("status", v)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="open">Open</SelectItem>
                  <SelectItem value="in_progress">In Progress</SelectItem>
                  <SelectItem value="converted">Converted</SelectItem>
                  <SelectItem value="closed">Closed</SelectItem>
                </SelectContent>
              </Select>
              {form.formState.errors.status && (
                <p className="text-sm text-red-500">{form.formState.errors.status.message}</p>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="notes">Notes</Label>
            <Textarea id="notes" {...form.register("notes")} />
          </div>
        </CardContent>
      </Card>

      <div className="flex gap-3 justify-end">
        {onCancel && (
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button type="submit" disabled={isLoading}>
          {isLoading ? "Saving..." : "Save"}
        </Button>
      </div>
    </form>
  );
}

