import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useQuery } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { api } from "@/lib/api";

const tokenSchema = z.object({
  token_date: z.string().min(1, "Token date is required"),
  agreement_id: z.string().min(1, "Agreement is required"),
  token_type: z.string().min(1, "Token type is required"),
  description: z.string().optional(),
  token_status: z.string().min(1, "Status is required"),
  tokens_used: z.coerce.number().nullable().optional(),
  client_employee_name: z.string().optional(),
  notes: z.string().optional(),
});

type TokenFormData = z.infer<typeof tokenSchema>;

interface TokenFormProps {
  initialData?: Partial<TokenFormData>;
  onSubmit: (data: TokenFormData) => Promise<void>;
  onCancel?: () => void;
  isLoading?: boolean;
}

export function TokenForm({ initialData, onSubmit, onCancel, isLoading }: TokenFormProps) {
  const form = useForm<TokenFormData>({
    resolver: zodResolver(tokenSchema),
    defaultValues: {
      token_date: new Date().toISOString().split("T")[0],
      agreement_id: "",
      token_type: "Consultation",
      description: "",
      token_status: "pending",
      tokens_used: null,
      client_employee_name: "",
      notes: "",
      ...initialData,
    },
  });

  const { data: agreementsData } = useQuery({
    queryKey: ["agreements-list"],
    queryFn: () => api.listAgreements({ page: 1, page_size: 1000 }),
  });

  const agreements = agreementsData?.items ?? [];

  const handleSubmit = async (data: TokenFormData) => {
    await onSubmit(data);
  };

  return (
    <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Token Details</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="token_date">Token Date *</Label>
              <Input id="token_date" type="date" {...form.register("token_date")} />
              {form.formState.errors.token_date && (
                <p className="text-sm text-red-500">{form.formState.errors.token_date.message}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="agreement_id">Agreement *</Label>
              <Select
                value={form.watch("agreement_id")}
                onValueChange={(v) => form.setValue("agreement_id", v)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select agreement" />
                </SelectTrigger>
                <SelectContent>
                  {agreements.map((agreement) => (
                    <SelectItem key={agreement.id} value={agreement.id}>
                      {agreement.agreement_id} - {agreement.service_name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {form.formState.errors.agreement_id && (
                <p className="text-sm text-red-500">{form.formState.errors.agreement_id.message}</p>
              )}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="token_type">Token Type *</Label>
              <Select
                value={form.watch("token_type")}
                onValueChange={(v) => form.setValue("token_type", v)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select type" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Consultation">Consultation</SelectItem>
                  <SelectItem value="Site Visit">Site Visit</SelectItem>
                  <SelectItem value="Design Review">Design Review</SelectItem>
                  <SelectItem value="Meeting">Meeting</SelectItem>
                  <SelectItem value="Report">Report</SelectItem>
                  <SelectItem value="Other">Other</SelectItem>
                </SelectContent>
              </Select>
              {form.formState.errors.token_type && (
                <p className="text-sm text-red-500">{form.formState.errors.token_type.message}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="token_status">Status *</Label>
              <Select
                value={form.watch("token_status")}
                onValueChange={(v) => form.setValue("token_status", v)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="pending">Pending</SelectItem>
                  <SelectItem value="approved">Approved</SelectItem>
                  <SelectItem value="completed">Completed</SelectItem>
                  <SelectItem value="cancelled">Cancelled</SelectItem>
                </SelectContent>
              </Select>
              {form.formState.errors.token_status && (
                <p className="text-sm text-red-500">{form.formState.errors.token_status.message}</p>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Description</Label>
            <Textarea id="description" {...form.register("description")} />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="tokens_used">Tokens Used</Label>
              <Input
                id="tokens_used"
                type="number"
                {...form.register("tokens_used")}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="client_employee_name">Client Employee Name</Label>
              <Input id="client_employee_name" {...form.register("client_employee_name")} />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="notes">Notes</Label>
            <Textarea id="notes" {...form.register("notes")} />
          </div>
        </CardContent>
      </Card>

      <div className="flex gap-3 justify-end">
        {onCancel && (
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button type="submit" disabled={isLoading}>
          {isLoading ? "Saving..." : "Save"}
        </Button>
      </div>
    </form>
  );
}

